ChartSummaryItem.definition:
interface ChartSummaryItem {
  /** Label shown above the value */
  label: string;
  /** Formatted value to display */
  value: string | number;
}

PieSlice.definition:
interface PieSlice {
  /** Display name */
  name: string;
  /** Numeric value */
  value: number;
  /** Slice fill colour */
  color?: string;
}
